// module.ts — the WebAssembly module, instantiated synchronously at import.
//
// The module bytes are embedded as base64 (./wasm-bytes.ts, generated by
// scripts/build-wasm.ts), decoded with atob, compiled with `new WebAssembly.Module`
// and instantiated with `new WebAssembly.Instance` — no `await init()`, no file or
// network access, the same code path on Node and Bun. The module imports nothing.
//
// Its memory is fixed (initial == max, set by the crate's build.rs), so `memory.grow`
// always fails and a view of `memory.buffer` never detaches. The loader proves that
// once, here, and then caches two views of the 64 KiB IO region for the lifetime of
// the module: `io8` (bytes) and `io64` (i64 slots, for the batch entry points).

import { WASM_BASE64, WASM_BYTE_LENGTH } from "./wasm-bytes.ts";

/** The raw exports of docs/contract.md § The WebAssembly ABI. */
export interface Abi {
  /** Address of the IO region. */
  io_ptr(): number;
  /** `ns` packed little-endian; writes 14 bytes at io[0..14]; returns the status (0 = OK). */
  encode(ns: number, snow: bigint): number;
  /** Reads `len` bytes at io[0..]; the snowflake (≥ 0) or −code. */
  decode(len: number): bigint;
  /** fmix64 first half of `k` as u64; the result as i32 (reinterpret with `>>> 0`). */
  hash32(k: bigint): number;
  /** `n` i64 at io[0..8n] → 14n bytes at io[8n..]; the count encoded before the first error. */
  encode_many(ns: number, n: number): number;
  /** `n × 14` bytes at io[0..14n] → `n` i64 at io[(14n + 7) & ~7 ..]; returns n. */
  decode_many(n: number): number;
  memory: WebAssembly.Memory;
}

/** Size of the IO region in bytes: the most `decode` accepts and the batch exports' budget. */
export const IO_LENGTH = 65536;

/** The largest batch the module accepts in one call: `round_up_8(14n) + 8n ≤ 65536`. */
export const BATCH_MAX = 2978;

/** The module's linear memory: three 64 KiB pages, fixed. */
const MEMORY_BYTES = 3 * 65536;

/**
 * base64 → bytes with `atob`. `Uint8Array.fromBase64` is not in Node 24's V8
 * (13.6); Bun has it, but one code path on both runtimes matters more than the
 * microseconds it would save on a 10 KB module.
 */
function fromBase64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const bytes = fromBase64(WASM_BASE64);
if (bytes.length !== WASM_BYTE_LENGTH) {
  throw new Error(`brd14-wasm: embedded module is ${bytes.length} bytes, expected ${WASM_BYTE_LENGTH}`);
}

/** The compiled module (for inspection: `WebAssembly.Module.imports/exports`). */
export const wasmModule = new WebAssembly.Module(bytes);

/** The one instance; its exports are the ABI. */
export const abi = new WebAssembly.Instance(wasmModule, {}).exports as unknown as Abi;

/** The instance's memory. */
export const memory = abi.memory;

// Fixed memory, proven once: a grow must fail and leave byteLength untouched. Only
// then are the cached views below safe for the lifetime of the module.
{
  const before = memory.buffer.byteLength;
  let grew = false;
  try {
    memory.grow(1);
    grew = true;
  } catch {
    // expected: initial == max
  }
  if (grew || memory.buffer.byteLength !== before || before !== MEMORY_BYTES) {
    throw new Error(`brd14-wasm: module memory is not fixed at ${MEMORY_BYTES} bytes (${before} → ${memory.buffer.byteLength}); views would detach`);
  }
}

/** Address of the IO region. */
export const IO_PTR = abi.io_ptr();
if (IO_PTR % 8 !== 0 || IO_PTR + IO_LENGTH > MEMORY_BYTES) {
  throw new Error(`brd14-wasm: IO region [${IO_PTR}, ${IO_PTR + IO_LENGTH}) is not an aligned region inside ${MEMORY_BYTES} bytes`);
}

/** The IO region as bytes. */
export const io8 = new Uint8Array(memory.buffer, IO_PTR, IO_LENGTH);

/** The IO region as i64 slots (the batch exports' input and output). */
export const io64 = new BigInt64Array(memory.buffer, IO_PTR, IO_LENGTH / 8);
